RENDERER=r'''import{SCOUT_SPINE_SINGLE_ASSET_CONFIG}from'../_shared/scout_sandbox_spine_single_asset_config.ts';import type{ScoutSandboxSpineSingleAssetMap}from'./spine_single_asset_model.ts';const TILE_SIZE=256,MAX_LAT=85.05112878;export type ScoutSpineAssetTile={z:number;x:number;y:number;left:number;top:number;url:string};export type ScoutSpineAssetFrame={zoom:number;width:number;height:number;tiles:ScoutSpineAssetTile[];marker:{left:number;top:number}};export type ScoutSpineAssetFrameOptions={tileUrlTemplate:string;minZoom?:number;maxZoom?:number};function clamp(lat:number){return Math.max(-MAX_LAT,Math.min(MAX_LAT,lat))}function wx(lon:number){return(lon+180)/360}function wy(lat:number){const r=clamp(lat)*Math.PI/180;return(1-Math.log(Math.tan(r)+1/Math.cos(r))/Math.PI)/2}function u(t:string,z:number,x:number,y:number){return t.replace('{z}',String(z)).replace('{x}',String(x)).replace('{y}',String(y))}export function buildScoutSpineSingleAssetRasterFrame(data:ScoutSandboxSpineSingleAssetMap,width:number,height:number,o:ScoutSpineAssetFrameOptions):ScoutSpineAssetFrame{const w=Math.max(280,Math.round(width||0)),h=Math.max(180,Math.round(height||0)),preferred=SCOUT_SPINE_SINGLE_ASSET_CONFIG[data.opportunity_type].zoom,z=Math.max(o.minZoom??5,Math.min(o.maxZoom??18,preferred)),world=TILE_SIZE*Math.pow(2,z),cx=wx(data.site_point.lon)*world,cy=wy(data.site_point.lat)*world,left=cx-w/2,top=cy-h/2,sx=Math.floor(left/TILE_SIZE),ex=Math.floor((left+w-1)/TILE_SIZE),sy=Math.floor(top/TILE_SIZE),ey=Math.floor((top+h-1)/TILE_SIZE),count=Math.pow(2,z),tiles:ScoutSpineAssetTile[]=[];for(let tx=sx;tx<=ex;tx++)for(let ty=sy;ty<=ey;ty++){if(ty<0||ty>=count)continue;const x=((tx%count)+count)%count;tiles.push({z,x,y:ty,left:tx*TILE_SIZE-left,top:ty*TILE_SIZE-top,url:u(o.tileUrlTemplate,z,x,ty)})}return{zoom:z,width:w,height:h,tiles,marker:{left:w/2,top:h/2}}}
'''
