MOUNT=r'''import type{ScoutSandboxSpineSingleAssetMap}from'./spine_single_asset_model.ts';import{buildScoutSpineSingleAssetRasterFrame,type ScoutSpineAssetFrameOptions}from'./spine_single_asset_map_renderer.ts';const TIMEOUT=7000,PNG='data:image/png;base64,';async function decode(s:string){if(!s.startsWith(PNG))throw new Error('Scout embedded raster tile is invalid');const b=atob(s.slice(PNG.length)),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return await createImageBitmap(new Blob([a],{type:'image/png'}))}export type ScoutSpineAssetMountOptions=ScoutSpineAssetFrameOptions&{attributionLabel:string;attributionUrl:string;timeoutMs?:number;embeddedTiles?:Record<string,string>;onError?:(e:Error)=>void;onReady?:()=>void};export function mountScoutSpineSingleAssetMap(container:HTMLElement,data:ScoutSandboxSpineSingleAssetMap,o:ScoutSpineAssetMountOptions){let dead=false,g=0,t:ReturnType<typeof setTimeout>|null=null,lw=-1,lh=-1;const clear=()=>{if(t!==null){clearTimeout(t);t=null}};const render=(force=false)=>{if(dead)return;const f=buildScoutSpineSingleAssetRasterFrame(data,container.clientWidth,container.clientHeight,o);if(!force&&f.width===lw&&f.height===lh)return;lw=f.width;lh=f.height;clear();g++;const n=g;container.replaceChildren();let loaded=0,settled=0,ready=false;const ok=()=>{if(dead||n!==g||ready)return;ready=true;clear();o.onReady?.()};const bad=()=>{if(dead||n!==g||ready)return;clear();o.onError?.(new Error('Scout raster tiles did not load'))};const embedded=f.tiles.length>0&&f.tiles.every(x=>o.embeddedTiles?.[x.url]);if(embedded){const c=document.createElement('canvas');c.width=f.width;c.height=f.height;c.style.position='absolute';c.style.inset='0';c.style.width=`${f.width}px`;c.style.height=`${f.height}px`;container.appendChild(c);const x=c.getContext('2d');if(!x){bad();return}void Promise.allSettled(f.tiles.map(async q=>{const m=await decode(o.embeddedTiles![q.url]);if(!dead&&n===g){x.drawImage(m,q.left,q.top,256,256);loaded++}m.close()})).then(()=>{settled=f.tiles.length;loaded>0?ok():bad()})}else for(const q of f.tiles){const i=document.createElement('img');i.alt='';i.draggable=false;i.decoding='async';i.loading='eager';i.referrerPolicy='origin';i.src=q.url;i.style.left=`${q.left}px`;i.style.top=`${q.top}px`;i.addEventListener('load',()=>{if(dead||n!==g)return;loaded++;settled++;if(loaded===1)ok()},{once:true});i.addEventListener('error',()=>{if(dead||n!==g)return;settled++;if(settled===f.tiles.length&&loaded===0)bad()},{once:true});container.appendChild(i)}const marker=document.createElement('span');marker.className='scout-site-marker';marker.style.left=`${f.marker.left}px`;marker.style.top=`${f.marker.top}px`;marker.title=data.display_name;marker.setAttribute('aria-hidden','true');const dot=document.createElement('span');dot.className='scout-site-marker-dot';marker.appendChild(dot);container.appendChild(marker);const attr=document.createElement('span');attr.className='scout-map-attribution';const link=document.createElement('a');link.href=o.attributionUrl;link.target='_blank';link.rel='noreferrer';link.textContent=o.attributionLabel;attr.appendChild(link);container.appendChild(attr);if(!f.tiles.length){bad();return}t=setTimeout(()=>loaded>0?ok():bad(),o.timeoutMs??TIMEOUT)};render(true);return{resize(){render(false)},destroy(){if(dead)return;dead=true;g++;clear();container.replaceChildren()}}}
'''
