TEST=r'''import assert from'node:assert/strict';import{readFile}from'node:fs/promises';import{build}from'esbuild';const d=new URL('./',import.meta.url);async function bundle(p){const r=await build({entryPoints:[new URL(p,d).pathname],bundle:true,format:'esm',platform:'node',target:'node22',write:false});return await import(`data:text/javascript;base64,${Buffer.from(r.outputFiles[0].text).toString('base64')}`)}const cfg=await bundle('../_shared/scout_sandbox_spine_single_asset_config.ts'),model=await bundle('spine_single_asset_model.ts'),renderer=await bundle('spine_single_asset_map_renderer.ts'),manifest=await bundle('../_shared/scout_sandbox_manifest.ts');for(const type of cfg.SCOUT_SPINE_SINGLE_ASSET_TYPES){const c=cfg.SCOUT_SPINE_SINGLE_ASSET_CONFIG[type],payload={contract_version:'spine_single_asset_map_v1',opportunity_type:type,candidate_key:`fixture:${type}`,source_kind:c.sourceKind,signal_kind:c.signalKinds[0],display_name:c.displayName,status_label:c.statusLabel,signal_strength:'medium',confidence:.8,observed_at:'2026-09-16T00:00:00Z',time_sensitive:false,why_now:'Bounded fixture evidence.',location_label:'Fixture location',site_point:{lon:c.center.lon,lat:c.center.lat,geometry_type:'Point',semantics:'source_opportunity_point'},target:{target_class:'infrastructure_asset',resolution_status:'stable_external_key',name:c.displayName},buyer:{resolution_status:'unresolved',name:null,contact_status:'unresolved',procurement_status:'unresolved'},facts:c.factLabels.map((label)=>({label,value:'fixture'})),related_signals:[],guardrail:c.guardrail};const map=model.normalizeScoutSandboxSpineSingleAssetMap(type,payload);assert.ok(map,`${type} map normalizer`);const opp=model.buildScoutSandboxSpineSingleAssetOpportunity(map);assert.ok(model.normalizeScoutSandboxSpineSingleAssetOpportunity(type,opp),`${type} opportunity normalizer`);const f=renderer.buildScoutSpineSingleAssetRasterFrame(map,456,210,{tileUrlTemplate:'https://sandbox.invalid/map-tile/{z}/{x}/{y}.png'});assert.equal(f.zoom,c.zoom);assert.ok(f.tiles.length>0&&f.tiles.length<=manifest.SCOUT_SANDBOX_MAX_EMBEDDED_RASTER_TILES);for(const t of f.tiles)assert.equal(manifest.isScoutSandboxRasterTileAllowed(t.z,t.x,t.y),true,`${type} tile ${t.z}/${t.x}/${t.y}`)}const migration=await readFile(new URL('../../migrations/20260916043000_add_spine_single_asset_sandbox.sql',d),'utf8');assert.ok(migration.includes("set search_path to 'pg_catalog'"));assert.ok(migration.includes('extensions.st_x'));assert.ok(migration.includes('extensions.st_y'));assert.ok(migration.includes('extensions.geometry'));assert.ok(migration.includes('grant execute on function public.scout_get_component_sandbox_asset_v1_internal(text) to service_role'));assert.equal(/(?:bridge|construction_window|dam|landfill|roof_lifecycle):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f-]{27}/i.test(migration),false,'migration must not pin generated opportunity UUID keys');console.log(`Scout generic single-asset checks passed for ${cfg.SCOUT_SPINE_SINGLE_ASSET_TYPES.length} types.`)
'''
write(COMP/'spine_single_asset_map_renderer_test.mjs',TEST)

# Package test and predeploy smoke.
path=COMP/'package.json';text=path.read_text();text=text.replace('node telecom_change_map_renderer_test.mjs &&','node telecom_change_map_renderer_test.mjs && node spine_single_asset_map_renderer_test.mjs &&',1);path.write_text(text)
path=COMP/'sandbox_predeploy_smoke_test.mjs';text=path.read_text();anchor="  telecom_change: 'telecom_change_map_renderer_test.mjs',\n";addition=anchor+''.join(f"  {t}: 'spine_single_asset_map_renderer_test.mjs',\n" for t in ['bridge','construction_site','dam','mine_quarry','landfill','rail_crossing','roof_lifecycle','solar_lifecycle']);
if anchor not in text:raise RuntimeError('predeploy smoke anchor missing');path.write_text(text.replace(anchor,addition,1))

# Docs: owner-approved batched release while preserving one-card/one-type semantics.
for name in ['DESIGN_CONTRACT.md','MAP_CONTRACT.md']:
 p=COMP/name;t=p.read_text();t+='''\n\n## Owner-approved remaining single-asset batch — 2026-09-16\n\nThe owner approved completing the remaining non-special-domain single-asset opportunity families before moving to multi-asset/network opportunities. Each card/result still represents exactly one opportunity type and one bounded evidence contract; batching authorizes a combined implementation/release cadence, not mixed maps or cross-type inference. The first batch covers bridge, construction site, dam, mine/quarry, landfill, rail crossing, roof lifecycle, and solar lifecycle through the shared single-site registry. Agriculture and forest-health/ecology remain outside this batch. Event-detailing remains in the single-asset phase but is held until its current event-source evidence is cleaned rather than freezing malformed venue text into a durable contract.\n''';p.write_text(t)
